import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/services/auth_service.dart';
import '../../../l10n/app_localizations.dart';
import '../../providers/app_state.dart';
import '../../widgets/app_drawer.dart';
class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context){final app=context.watch<AppState>();final l=AppLocalizations.of(context);return Scaffold(appBar:AppBar(title:Text(l.t('settings'))),drawer:const AppDrawer(),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField(value:app.languageCode,decoration:InputDecoration(labelText:l.t('changeLanguage')),items:const [DropdownMenuItem(value:'sw',child:Text('Kiswahili')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v)=>app.setLanguage(v!)),SwitchListTile(title:Text(l.t('darkMode')),value:app.darkMode,onChanged:app.toggleDark),ListTile(leading:const Icon(Icons.person),title:Text(l.t('profile'))),ListTile(leading:const Icon(Icons.lock),title:Text(l.t('changePassword')),onTap:()=>_password(context)),FilledButton.icon(onPressed:()=>context.read<AuthService>().signOut(),icon:const Icon(Icons.logout),label:Text(l.t('logout')))]));}void _password(BuildContext context){final l=AppLocalizations.of(context);final p=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:Text(l.t('changePassword')),content:TextField(controller:p,obscureText:true,decoration:InputDecoration(labelText:l.t('password'))),actions:[FilledButton(onPressed:(){context.read<AuthService>().changePassword(p.text);Navigator.pop(context);},child:Text(l.t('save')))]));}}
